import json
from pathlib import Path

sources = json.loads(Path('source.json').read_text())
references = json.loads(Path('reference-targets.json').read_text())
answers = []


def add(index, text, reason, notes, removed=None, benefit=None):
    source = sources[index]
    answer = {k: source[k] for k in ('code_id', 'source_id', 'source_sha256', 'number')}
    answer.update(proposed_xml=text.strip(), reason=reason, review_notes=notes, status='rewrite_draft')
    if removed:
        answer.update(change_type='normative_reduction',
                      reform_policy_id='editorial_direction_2026_10_19',
                      removed_provisions=removed)
    if benefit:
        answer['benefit_review'] = benefit
    answers.append(answer)


add(0, """
<p>La personne qui relève du régime d'assurance contre les accidents du travail et les maladies professionnelles des non-salariés agricoles, défini au chapitre II du titre V du livre VII du code rural et de la pêche maritime, et exerce simultanément une activité salariée relevant du régime général de sécurité sociale ou du régime des salariés agricoles perçoit l'indemnité journalière mentionnée à l'article L. 323-1 du présent code si elle est victime, dans le cadre de son activité non salariée agricole, d'un accident du travail ou d'une maladie professionnelle entraînant une incapacité de travail. Cette indemnité s'ajoute à celle versée par ce régime des non-salariés agricoles, sous réserve que cette personne remplisse les conditions fixées à l'article L. 313-1 du présent code, le cas échéant selon les modalités prévues à l'article L. 742-3 du code rural et de la pêche maritime.</p>
<p>Pour l'application du premier alinéa, aucun organisme ne peut exiger de l'assuré une nouvelle production des pièces ou données exactes et à jour qui lui sont déjà légalement accessibles ou qui lui ont été régulièrement transmises par l'autre régime. Cette dispense ne supprime ni la constatation de l'incapacité, ni les conditions d'ouverture des droits, ni les contrôles légalement prévus. Elle n'autorise aucun échange de données en dehors des règles de confidentialité applicables.</p>
<p>Le premier alinéa s'applique aux accidents du travail et aux maladies professionnelles déclarés à compter du 1er janvier 2021. La dispense de nouvelle production s'applique aux pièces sollicitées à compter de l'entrée en vigueur de la loi portant la présente rédaction, y compris dans les dossiers en cours, sans remise en cause des prestations déjà dues.</p>
""", "Réécriture du cumul d'indemnités en identifiant séparément l'activité à l'origine du risque et l'activité salariée simultanée. Les conditions assurantielles et le cumul favorable sont conservés à droit constant. Réforme de fond documentaire : interdiction opposable de redemander à l'assuré les pièces déjà régulièrement reçues ou légalement accessibles, sans déclaration de remplacement.",
    "Conserver le champ agricole non salarié du fait dommageable, les deux régimes possibles de l'activité salariée, L323-1, L313-1 et la modalité éventuelle de L742-3. La date du 1er janvier 2021 vient de la note d'application de l'article 68 de la loi 2020-1576 ; elle n'est pas la date de la réforme proposée. L742-3 est extérieur au corpus fourni et son contenu n'est pas reconstitué. Coordonner les formulaires et demandes de pièces de ces régimes avec la dispense ; les conditions médicales et contributives restent nécessaires à l'assurance du revenu.",
    ["Nouvelle production par l'assuré des pièces exactes et à jour déjà reçues ou légalement accessibles pour la coordination des deux indemnisations."])

add(1, """
<p>La personne salariée qui relève du régime général de sécurité sociale ou du régime des salariés agricoles et exerce simultanément une activité non salariée agricole relevant du régime défini au chapitre II du titre V du livre VII du code rural et de la pêche maritime perçoit l'indemnité journalière mentionnée à l'article L. 732-4 du même code si elle est victime, dans le cadre de son activité salariée, d'un accident du travail ou d'une maladie professionnelle entraînant une incapacité de travail. Cette indemnité s'ajoute à celle versée par le régime général d'assurance contre les accidents du travail et les maladies professionnelles des salariés ou par le régime d'assurance contre les accidents du travail et les maladies professionnelles des salariés agricoles, sous réserve que cette personne remplisse les conditions fixées à ce même article L. 732-4.</p>
<p>Pour l'application du premier alinéa, aucun organisme ne peut exiger de l'assuré une nouvelle production des pièces ou données exactes et à jour qui lui sont déjà légalement accessibles ou qui lui ont été régulièrement transmises par l'autre régime. Cette dispense ne supprime ni la constatation de l'incapacité, ni les conditions d'ouverture des droits, ni les contrôles légalement prévus. Elle n'autorise aucun échange de données en dehors des règles de confidentialité applicables.</p>
<p>Le premier alinéa s'applique aux accidents du travail et aux maladies professionnelles déclarés à compter du 1er janvier 2023. La dispense de nouvelle production s'applique aux pièces sollicitées à compter de l'entrée en vigueur de la loi portant la présente rédaction, y compris dans les dossiers en cours, sans remise en cause des prestations déjà dues.</p>
""", "La règle réciproque de L172-1-1 est réécrite : le risque survient ici dans l'activité salariée et l'indemnité supplémentaire est celle de L732-4. Le cumul favorable demeure, pour les assurés actuels et futurs éligibles. La réforme interdit la remise répétée de pièces déjà disponibles ; elle ne modifie pas les conditions de l'indemnité agricole.",
    "Ne pas inverser l'activité d'origine de l'accident avec celle ouvrant l'indemnité complémentaire. La note du III de l'article 94 de la loi 2022-1616 fixe le champ aux déclarations à compter du 1er janvier 2023 ; cette transition est conservée. L732-4, extérieur aux cinq codes disponibles, est maintenu dans ses deux fonctions, désignation de l'indemnité et conditions d'accès, sans inventer ses paramètres. Harmoniser les demandes de justificatifs sans étendre l'accès aux données de santé.",
    ["Nouvelle production par l'assuré des pièces exactes et à jour déjà reçues ou légalement accessibles pour la coordination des indemnisations agricole et salariée."])

add(2, """
<p>La coordination entre régimes pour l'indemnisation de la maladie ou de la maternité repose sur le maintien des droits prévu à l'article L. 161-8.</p>
<p>Lorsque l'assuré ne peut bénéficier de ce maintien et que le présent code ou le code rural et de la pêche maritime subordonne l'indemnisation de la maladie ou de la maternité à des conditions préalables d'affiliation, de cotisation ou de durée du travail, les organismes de sécurité sociale prennent en compte toutes les périodes d'affiliation, toutes les cotisations versées et toutes les périodes de travail accomplies. Cette prise en compte s'étend aux périodes et cotisations relevant d'un autre régime de sécurité sociale régi par l'un de ces deux codes.</p>
<p>Les organismes mettent en œuvre cette totalisation à partir des informations qu'ils détiennent ou auxquelles ils ont légalement accès. Ils ne peuvent demander à l'assuré de produire à nouveau les justificatifs exacts et à jour correspondant à ces informations. Aucune attestation supplémentaire d'un autre régime n'est exigée lorsque ces informations exactes et à jour sont déjà légalement accessibles à la caisse chargée des prestations. Les autres conditions d'ouverture des droits et les règles de confidentialité restent applicables.</p>
<p>Les dispenses de nouvelle production et d'attestation supplémentaire s'appliquent aux pièces sollicitées à compter de l'entrée en vigueur de la loi portant la présente rédaction, y compris pour les demandes en cours. Elles ne remettent pas en cause les droits déjà ouverts.</p>
""", "Les deux voies sont distinguées : maintien des droits, puis totalisation interrégimes à défaut. Aucune période acquise n'est effacée. La réduction de fond porte sur la preuve : l'organisme utilise les informations déjà détenues ou légalement accessibles, sans seconde remise par l'assuré ni attestation interrégimes supplémentaire pour des informations déjà accessibles.",
    "Le premier alinéa reste celui auquel renvoie la condition du second. L161-8 comprend aussi les nouvelles activités dont les indemnités de maladie sont nulles et, sous conditions réglementaires, les indemnités forfaitaires de maternité ; ces cas ne sont pas exclus. R172-12-1 à R172-12-3 ont été lus intégralement dans le corpus : coordonner précisément l'attestation intercaisses du premier alinéa de R172-12-2 et les pièces des périodes de revenus de remplacement imposées à l'assuré au second, lorsque les informations sont déjà disponibles. Les équivalences, régimes débiteurs et dates de rattachement de R172-12-1 et R172-12-3 restent inchangés, notamment le congé supplémentaire de naissance ajouté en 2026. Ces règlements ne sont pas réécrits par le lot. Affiliation, cotisations et travail sont des critères de protection sociale, pas l'ancienneté de rupture chez un employeur. Les paramètres assurantiels restent nécessaires pour déterminer les droits ; aucune affiliation agricole ou publique n'est absorbée par le contrat unique. Ne pas étendre les accès légaux aux données.",
    ["Production répétée des justificatifs de périodes et de cotisations dont les informations exactes et à jour sont déjà détenues ou légalement accessibles aux organismes.", "Attestation interrégimes supplémentaire pour des informations de totalisation exactes et à jour déjà légalement accessibles à la caisse chargée des prestations."])

add(3, """
<p>Les régimes d'assurance invalidité coordonnent les droits des personnes qui ont relevé successivement ou alternativement de plusieurs régimes de salariés, d'un régime de salariés et d'un régime de non-salariés, ou de plusieurs régimes de travailleurs non salariés.</p>
<p>Lorsque le montant de la pension servie par un régime représente une fraction annuelle des revenus soumis à cotisations au sens de l'article L. 242-1, perçus au cours des dix années civiles d'assurance les plus avantageuses, un décret en Conseil d'État fixe les conditions d'ouverture, de maintien et de calcul des droits à pension d'invalidité dans les régimes concernés.</p>
<p>Le présent article s'applique également au régime d'assurance invalidité des ministres des cultes et des membres des congrégations et collectivités religieuses.</p>
<p>Pour une pension relevant de cette coordination, la demande peut être déposée auprès de l'un des régimes concernés. Si le régime saisi n'est pas compétent pour la traiter, il la transmet à l'organisme compétent, sans nouveau dépôt par l'assuré. Cette transmission ne modifie ni la désignation du régime débiteur, ni les règles de substitution ou de cumul des pensions. Aucune nouvelle production de pièces exactes et à jour déjà régulièrement reçues ou légalement accessibles ne peut être exigée de l'assuré. Les échanges respectent les règles de confidentialité et chaque régime conserve l'examen des conditions relevant de sa compétence.</p>
<p>La dispense de nouveau dépôt s'applique aux demandes présentées à compter de l'entrée en vigueur de la loi portant la présente rédaction. La dispense de nouvelle production de pièces s'applique également aux dossiers en cours. Les droits et dates d'effet déjà acquis sont préservés. L'entrée en vigueur au 1er janvier 2018 des règles de coordination issues de l'article 62 de la loi n° 2016-1827 du 23 décembre 2016 demeure sans changement.</p>
""", "Réécriture de la coordination invalidité en conservant ses trois configurations d'affiliations, son extension aux cultes et le calcul sur les dix meilleures années. Réforme de fond : garantie législative d'acheminement de la demande sans second dépôt et suppression des pièces en double. La transmission déjà prévue réglementairement dans certains cas n'est pas comptée comme une suppression nouvelle ; la garantie est généralisée au champ de l'article, sans modifier le régime débiteur ni les cumuls protecteurs.",
    "L242-1 définit les revenus soumis à cotisations ; son II exclut notamment certaines indemnités de rupture et contributions de protection complémentaire. Le renvoi ne crée pas une assiette brute supplémentaire et ne neutralise aucune exclusion. R172-16 à R172-21-4 ont été lus intégralement dans le corpus : R172-21-1 organise déjà une transmission sous quinze jours pour les affiliations simultanées de son champ et des examens subsidiaires favorables, qu'il faut conserver. Ce délai administratif n'est pas le préavis privé. Les règles de régime débiteur, substitution, cumul et minimum de pension coordonnée des règlements demeurent ; la nouvelle dispense ne vaut pas attribution de plusieurs pensions pour le même risque. Coordonner les formulaires et preuves, notamment celles de R172-19 pour les activités anciennes, sans réécrire ici ces règlements. Le 1er janvier 2018 est la date historique de l'article 62 III de la loi 2016-1827, distincte de la prise d'effet de la simplification. Aucun seuil d'indemnité de rupture ne s'applique à ce calcul.",
    ["Nouveau dépôt imposé à l'assuré auprès du régime compétent après réception par un autre régime d'une demande relevant de la coordination, dans les cas non déjà dispensés.", "Nouvelle production de pièces exactes et à jour déjà reçues ou légalement accessibles aux régimes coordonnant l'invalidité."])

add(4, """
<p>L'assuré qui a relevé successivement ou alternativement d'un régime spécial et du régime général, dans l'un ou l'autre ordre, peut cumuler les avantages auxquels ses affiliations lui donnent droit, dans les conditions et limites fixées par décret.</p>
<p>Les caisses et services gestionnaires des régimes de base d'assurance vieillesse se communiquent, directement ou indirectement, les données de carrière nécessaires à la liquidation des pensions de leurs ressortissants, notamment les périodes prises en compte, la durée d'assurance et la nature des trimestres validés. Ces données sont communiquées au plus tard en décembre de l'année précédant le cinquante-sixième anniversaire de l'assuré.</p>
<p>L'obligation de communication est satisfaite lorsque les données exactes et à jour sont déjà légalement accessibles au régime destinataire. Après l'échéance mentionnée au deuxième alinéa, les modifications nécessaires à la liquidation sont communiquées lors de la préparation ou de la liquidation de la pension, sans retransmission annuelle obligatoire en décembre. Aucune nouvelle production des mêmes justificatifs exacts et à jour ne peut être exigée de l'assuré. Les règles de confidentialité et le droit de faire rectifier les données demeurent applicables.</p>
<p>La suppression des retransmissions périodiques et des productions en double s'applique à compter de l'entrée en vigueur de la loi portant la présente rédaction. Elle n'impose pas de refaire les transmissions antérieures et ne réduit aucun droit à pension déjà constitué.</p>
""", "Le cumul entre régime général et régime spécial demeure. La réforme retire le rendez-vous obligatoire de retransmission chaque décembre après modification et dispense de toute copie déjà légalement accessible. L'échéance initiale précédant les cinquante-six ans et la communication des données modifiées nécessaires à la liquidation sont conservées ; l'assuré ne refournit pas les preuves déjà disponibles.",
    "La source impose une transmission initiale puis une transmission annuelle seulement en cas de modification, et non un rapport annuel général : seule cette échéance répétitive est supprimée. Les données actualisées restent nécessaires pour liquider les droits et leur correction reste possible. Coordonner les calendriers réglementaires et échanges de carrière pour qu'ils ne rétablissent pas la retransmission supprimée. Le cumul d'avantages est préservé pour toutes les affiliations éligibles ; les régimes spéciaux ne sont pas transformés en contrats privés.",
    ["Retransmission obligatoire en décembre de chaque année suivante lorsque des données de carrière ont été modifiées, remplacée par leur communication utile à la liquidation.", "Transmission en double de données de carrière exactes et à jour déjà légalement accessibles au régime destinataire et nouvelle remise des mêmes preuves par l'assuré."])

add(5, """
<p>Lorsqu'un assuré a droit à la fois à la majoration prévue à l'article L. 353-6 du présent code et à celle prévue à l'article L. 732-54-1 du code rural et de la pêche maritime, la majoration prévue à l'article L. 353-6 est servie en premier.</p>
""", "La règle de priorité est réécrite sans supprimer l'une des deux majorations ni modifier leurs conditions. Elle organise le service de droits favorables et n'impose ni prélèvement accessoire ni démarche autonome à retirer.",
    "Préserver les deux fondements et la priorité, sans transformer celle-ci en exclusion définitive de la majoration agricole. La note de l'article 87 VIII C de la loi 2025-199 rattache les dispositions visées aux pensions prenant effet à compter du 1er janvier 2026 ; cette application historique demeure. L353-6 a été lu dans le corpus : majoration de réversion sous plafond, non impôt sur un décès. L732-54-1 reste un renvoi extérieur dont le texte intégral n'est pas fourni ; aucun taux ou mode d'écrêtement n'est inventé. La réforme successorale ne supprime pas ces droits sociaux.")

add(6, """
<p>I. - Lorsqu'un assuré relève ou a relevé successivement, alternativement ou simultanément du régime général de sécurité sociale, du régime des salariés agricoles et du régime social des indépendants, sa demande de liquidation d'un droit à pension de vieillesse auprès de l'un des régimes concernés vaut demande de liquidation de toutes ses pensions de droit direct auprès de ces régimes. Le total de ses droits à pension est déterminé selon les règles suivantes.</p>
<p>Pour chaque année civile ayant donné lieu à affiliation à l'assurance vieillesse auprès de l'un des régimes concernés, sont additionnés :</p>
<p>1° Toutes les rémunérations ayant donné lieu à cotisation d'assurance vieillesse, pour déterminer le nombre annuel de trimestres d'assurance de l'ensemble des régimes concernés ;</p>
<p>2° Toutes les périodes d'assurance retenues pour déterminer le droit à pension dans l'un de ces régimes ;</p>
<p>3° Les salaires et revenus annuels de base de chaque régime, dans la limite, pour leur somme, du plafond annuel défini au premier alinéa de l'article L. 241-3 en vigueur pour l'année considérée.</p>
<p>Le nombre de trimestres validés résultant de la somme des périodes mentionnées aux 1° et 2° du présent I ne peut dépasser quatre par an.</p>
<p>II. - Un seul des régimes concernés calcule la pension à partir des paramètres du I, selon ses modalités et règles de liquidation. Un décret en Conseil d'État fixe la règle de priorité qui désigne le régime compétent pour liquider la pension.</p>
<p>III. - Le régime qui calcule et sert la pension en supporte toute la charge. Un décret précise les modalités de compensation financière forfaitaire entre les régimes concernés.</p>
<p>III bis. - Le présent article s'applique aux assurés nés à compter du 1er janvier 1953.</p>
<p>III ter. - Le II s'applique également aux pensions de réversion et aux pensions d'orphelin lorsque les pensions de vieillesse de droit propre de l'assuré décédé, absent ou disparu ont relevé ou auraient relevé du présent article.</p>
<p>IV. - Sauf disposition contraire, un décret en Conseil d'État détermine les modalités d'application du présent article.</p>
""", "Réécriture complète de la liquidation unique sans changer la demande réputée commune, les trois agrégations annuelles, le plafond, les quatre trimestres, la charge financière et les bénéficiaires de la coordination. Le mécanisme supprime déjà les demandes multiples de droit direct ; sa réécriture n'est pas présentée comme une suppression nouvelle. Les limites de décompte évitent le double emploi des mêmes périodes.",
    "Conserver les onze alinéas et I, II, III, III bis, III ter, IV. Le renvoi de I 3° vise uniquement le plafond annuel du premier alinéa de L241-3, situé dans le I de sa proposition ; il ne vise ni les taux de transfert ni les comptes de capitalisation. La dénomination régime social des indépendants est historique dans la source : sa mise en concordance avec l'intégration au régime général demande un contrôle distinct et n'est pas faite silencieusement. Le futur transfert financé de L241-3 nécessitera une coordination du calcul des droits futurs, sans double attribution répartition/capital ; cette coordination n'est pas déclarée réalisée ici. La note A du VIII de l'article 87 de la loi 2025-199 vise certaines modifications à compter du 1er janvier 2025, pas une nouvelle naissance générale de la liquidation unique. Le III ter étend le II, et non implicitement tout le I, aux réversions et orphelins.")

add(7, """
<p>Lorsqu'un assuré relève ou a relevé alternativement, successivement ou simultanément de plusieurs régimes obligatoires de base d'assurance vieillesse et que ses droits à pension dans l'un d'eux sont inférieurs à un seuil fixé par décret, le régime auprès duquel il compte la plus longue durée d'assurance peut verser cette pension pour le compte du régime qui la doit. Les régimes déterminent cette durée à partir des données de carrière exactes et à jour qu'ils détiennent ou auxquelles ils ont légalement accès, sans en exiger une nouvelle justification par l'assuré. Un décret précise les modalités de mise en œuvre du présent article, notamment le remboursement entre les régimes concernés.</p>
<p>Le premier alinéa peut également s'appliquer aux pensions de réversion. Un décret en Conseil d'État fixe les adaptations nécessaires, notamment pour tenir compte de l'évolution dans le temps des pensions de réversion servies.</p>
<p>Le présent article s'applique aux assurés dont l'ensemble des pensions prend effet à compter du 1er janvier 2016. La dispense de nouvelle justification s'applique aux pièces sollicitées à compter de l'entrée en vigueur de la loi portant la présente rédaction, y compris dans les dossiers en cours, sans remise en cause des pensions et remboursements déjà dus.</p>
""", "La faculté de paiement groupé des petites pensions et son extension possible aux réversions sont préservées. La réforme retire la justification répétée par l'assuré de sa plus longue durée d'assurance lorsque les régimes disposent déjà des données exactes : cette vérification leur incombe à partir de ces données, sans nouveau dossier de remplacement.",
    "Le seuil demeure réglementaire et n'est ni fixé ni relevé ici. Le régime payeur agit pour le compte du régime débiteur ; aucune charge de pension n'est transférée sans remboursement. Le premier alinéa reste la cible du renvoi relatif aux réversions. La note de l'article 44 V de la loi 2014-40 fixe l'application aux assurés dont toutes les pensions prennent effet à compter du 1er janvier 2016. Adapter les pièces réglementaires à la dispense tout en conservant les adaptations des réversions variables dans le temps.",
    ["Justification renouvelée par l'assuré de sa plus longue durée d'assurance lorsque les données de carrière exactes et à jour sont déjà détenues ou légalement accessibles aux régimes."])

add(8, """
<p>Un décret désigne le régime chargé de valider les périodes assimilées lorsque l'assuré a relevé successivement, alternativement ou simultanément de plusieurs régimes de base d'assurance vieillesse.</p>
""", "L'ordre de la phrase est simplifié sans changer les trois configurations de pluralité de régimes ni l'attribution réglementaire de la charge de validation. Cette attribution permet de reconnaître les périodes assimilées ; l'abroger créerait un risque de non-prise en compte des droits plutôt qu'un allègement utile.",
    "La charge de validation n'est ni une cotisation supplémentaire ni un plafond de durée du contrat. Le décret de répartition entre régimes reste nécessaire pour éviter une période sans régime responsable. Les droits attachés aux périodes assimilées restent ouverts pour les situations futures éligibles. Aucun nouveau décompte, critère d'affiliation ou taux n'est ajouté.")

add(9, """
<p>Les assurés qui ont accompli au moins dix années de service comme sapeur-pompier volontaire, continues ou non, ont droit à des trimestres supplémentaires pris en compte pour déterminer le taux de calcul de leur pension et leur durée d'assurance dans le régime. Un décret en Conseil d'État fixe les conditions et limites de ce droit. Il précise notamment le régime chargé de valider ces trimestres lorsque l'assuré a relevé successivement, alternativement ou simultanément de plusieurs régimes de base d'assurance vieillesse.</p>
""", "La phrase longue est scindée tout en conservant le droit aux trimestres supplémentaires, le seuil de dix ans non nécessairement continus, ses deux effets sur la pension et la désignation du régime responsable. Le texte est un avantage de retraite maintenu pour les futurs services éligibles ; il ne comporte pas de prélèvement ou d'agrément autonome à supprimer.",
    "Ne pas convertir dix années de volontariat en ancienneté salariée ni y appliquer le seuil d'un an de l'indemnité ordinaire de rupture. Le décret en Conseil d'État conserve ses conditions et limites ainsi que le rattachement interrégimes. Aucun nombre de trimestres supplémentaire n'est inventé ; la durée de service peut être discontinue. Le transfert futur vers la capitalisation ne réduit pas cet avantage par simple renvoi.")

add(10, """
<p>L'assuré qui a relevé du régime général de sécurité sociale, du régime des salariés agricoles ou du régime social des indépendants et peut bénéficier, dans un ou plusieurs de ces régimes, du minimum de pension prévu à l'article L. 351-10 reçoit ce minimum si le montant mensuel total de ses pensions personnelles de retraite ne dépasse pas un montant fixé par décret. Ce total comprend les pensions attribuées par les régimes légaux ou rendus légalement obligatoires, de base et complémentaires, français et étrangers, ainsi que par les régimes des organisations internationales ; ces pensions sont, le cas échéant, portées au minimum de pension.</p>
<p>Si ce montant est dépassé, la majoration résultant de l'article L. 351-10 est réduite du montant du dépassement.</p>
<p>Un décret fixe les modalités d'application du présent article lorsque l'assuré peut bénéficier du minimum prévu à l'article L. 351-10 dans plusieurs régimes.</p>
<p>Pour déterminer le total mentionné au premier alinéa, les organismes utilisent les informations exactes et à jour qu'ils détiennent ou auxquelles ils ont légalement accès. Ils ne peuvent en demander à nouveau les justificatifs à l'assuré. Cette dispense n'étend pas leurs droits d'accès aux données et ne dispense pas de communiquer les éléments nécessaires dont ils ne disposent pas.</p>
<p>La dispense de nouvelle production s'applique aux pièces sollicitées à compter de l'entrée en vigueur de la loi portant la présente rédaction, y compris pour les demandes en cours, sans modifier le plafond ni les règles applicables aux pensions déjà dues.</p>
""", "Le minimum contributif reste ouvert aux assurés futurs éligibles. L'énumération des pensions prises en compte et l'écrêtement du seul supplément sont conservés, pour maintenir le ciblage du minimum. La réforme supprime la nouvelle production des justificatifs de pensions déjà connus légalement des organismes, sans supprimer la preuve des pensions étrangères ou autres données indisponibles.",
    "Le total porte sur les pensions personnelles attribuées, pas sur toutes les ressources du foyer ni sur un capital non liquidé. Le deuxième alinéa réduit la majoration, non la pension contributive de base. L351-10 conserve ses propres conditions de taux plein, durée, périodes assimilées admises, suppléments et revalorisation ; aucune exonération ou majoration n'est effacée. La dénomination historique du régime social des indépendants est conservée avec la même réserve de concordance que L173-1-2. Adapter les justificatifs et échanges interrégimes sans affirmer que toutes les pensions étrangères sont déjà accessibles.",
    ["Nouvelle production des justificatifs de pensions personnelles dont les montants exacts et à jour sont déjà détenus ou légalement accessibles aux organismes appréciant le minimum."])

add(11, """
<p>Lorsqu'un assuré peut bénéficier du minimum de pension dans plusieurs régimes au titre de l'article L. 351-10 du présent code et de l'article L. 17 du code des pensions civiles et militaires de retraite, un décret fixe les modalités d'application de l'article L. 173-2 du présent code et des septième et huitième alinéas de cet article L. 17, dans les cas où ces dispositions lui sont applicables.</p>
""", "La condition de pluralité de minima est placée en tête et le champ de l'habilitation est conservé à droit constant. Le texte coordonne un avantage entre régimes privé et public ; le supprimer pourrait priver un bénéficiaire du minimum ou de sa correcte répartition. Aucune nouvelle formalité individuelle n'est instituée.",
    "Conserver exactement les septième et huitième alinéas de L17, renvoi à un régime public distinct du code du travail. L17 n'est pas fourni dans les cibles ni dans les cinq codes du corpus : sa numérotation actuelle reste un point documentaire à contrôler, sans lui attribuer un contenu reconstitué. La rédaction ne corrige ni ne déplace ce renvoi. Le minimum L351-10 et le total de pensions L173-2 restent à leur champ propre ; ni ancienneté d'un an, ni préavis de quinze jours, ni plafond de six mois d'indemnité privée ne les régissent.")

add(12, """
<p>Pour un même enfant, le total des trimestres attribués à chaque parent en application des II et III de l'article L. 351-4 ou de dispositions qui renvoient à cet article ne peut dépasser quatre. Lorsque les parents relèvent de régimes d'assurance vieillesse différents, la répartition de ces trimestres entre eux obéit, le cas échéant, aux mêmes II et III.</p>
""", "Les deux fonctions du texte sont rendues explicites : plafond individuel de trimestres et répartition entre parents affiliés à des régimes différents. Les majorations d'éducation et d'adoption demeurent, y compris pour les futurs enfants ouvrant droit ; les règles de répartition protectrices ne sont pas supprimées sous couvert de simplification.",
    "Le plafond de quatre porte sur le total attribué à chaque parent au titre des II et III, et non sur un nouveau total commun aux deux parents, ni sur les quatre trimestres de maternité du I de L351-4. Le texte intégral de L351-4 et ses notes ont été lus dans le corpus : les garanties de répartition, notamment le minimum de deux trimestres pour la mère dans les cas prévus, restent applicables. La note de l'article 65 VIII de la loi 2009-1646 fixe l'application aux pensions prenant effet à compter du 1er avril 2010 ; la note propre aux modifications de L351-4 vise aussi des pensions à compter du 1er septembre 2026. Ces dates d'application des textes respectifs sont conservées, sans faire du présent article une refonte de L351-4.")

add(13, """
<p>Lorsque les deux parents remplissent, pour un même enfant, les conditions ouvrant droit à des périodes d'assurance au titre de l'accouchement, de la grossesse, de l'adoption ou de l'éducation, l'un dans le régime général d'assurance vieillesse ou un régime appliquant les mêmes dispositions que l'article L. 351-4, et l'autre dans un régime spécial de retraite, seules les règles du régime dont relève la mère de l'enfant s'appliquent. Si les deux parents sont de même sexe, les règles d'un seul régime s'appliquent, selon une priorité entre régimes définie par décret en Conseil d'État. Un décret fixe la liste des avantages des régimes spéciaux soumis au présent article.</p>
""", "La condition commune est placée avant la règle de priorité et le cas des parents de même sexe est isolé dans une phrase. Les quatre causes d'attribution de périodes et les droits relevant de la liste réglementaire sont intégralement conservés. La priorité évite un double emploi et laisse un régime responsable ; elle n'est pas une autorisation administrative à abroger.",
    "Maintenir la condition selon laquelle les deux parents remplissent les conditions dans les deux catégories de régimes, la priorité maternelle et l'exception de même sexe. Le renvoi à L351-4 ne supprime pas les avantages d'accouchement ou de grossesse du régime retenu. Le décret listant les avantages spéciaux n'est pas remplacé par un régime privé uniforme. Aucun plafond supplémentaire, choix obligatoire nouveau ou preuve répétée n'est introduit.")

add(14, """
<p>Lorsqu'un conjoint survivant bénéficie de plusieurs pensions de réversion, un décret désigne le régime chargé de verser la majoration prévue à l'article L. 353-5.</p>
""", "La désignation du payeur est formulée directement. La majoration pour enfant à charge attachée à la réversion demeure, avec ses conditions propres ; il ne s'agit ni d'un droit de succession ni d'un prélèvement supprimable au titre de la décision sur les décès.",
    "L353-5 a été lu intégralement dans le corpus : majoration forfaitaire pour enfant à charge sous conditions, avec exclusions de cumul et revalorisation propres. Le présent article répartit la charge du versement en cas de réversions multiples ; il ne retire aucun de ces droits et ne les réserve pas aux seuls décès antérieurs. Le décret de désignation reste nécessaire pour éviter l'absence de payeur. Aucune condition d'ancienneté d'emploi n'est ajoutée.")

add(15, """
<p>Lorsqu'un bénéficiaire a exercé successivement des activités professionnelles relevant de plusieurs caisses de régimes différents de non-salariés ou de régimes de salariés, des décrets en Conseil d'État fixent les conditions de répartition de la charge des allocations entre ces caisses.</p>
""", "Le fait déclenchant la coordination précède désormais la répartition de charge. Le champ des caisses, les activités successives et le niveau réglementaire sont conservés. La norme répartit le financement d'allocations et protège leur paiement ; l'abroger n'allégerait pas une démarche du bénéficiaire.",
    "Le mot allocations est conservé sans le remplacer par l'ensemble des pensions ou par un nouveau compte de capitalisation. Le présent article n'établit ni prélèvement sur le bénéficiaire, ni taux, ni obligation déclarative autonome. Les droits encore servis sur ces fondements restent protégés ; aucune extinction n'est déduite de l'ancienneté du texte.")

add(16, """
<p>Les régimes de retraite dont relevaient les clercs, secrétaires et employés d'avoué, d'agréé et d'avocat sont coordonnés avec les régimes dont ces personnes relèvent ou peuvent relever du fait de leur nouvelle profession ou de leur nouvel emploi. Le fonds d'organisation de la nouvelle profession d'avocat garantit le paiement des sommes nécessaires au maintien des droits acquis ou en cours d'acquisition au 16 septembre 1972, y compris les droits relevant des régimes de retraite complémentaires.</p>
""", "La coordination et la garantie sont réécrites avec des sujets explicites. Le texte protège des droits historiques, notamment complémentaires ; ni la garantie ni le financement de ces engagements ne sont supprimés au seul motif de leur ancienneté.",
    "La date du 16 septembre 1972 qualifie les droits acquis ou en cours d'acquisition, non la date d'entrée en vigueur d'une réforme future. Conserver les trois catégories de personnels, les professions mentionnées, les régimes de la nouvelle activité et les droits complémentaires. Aucune nouvelle contribution ni compétence du fonds n'est inventée. L'état actuel du fonds n'est pas documenté par le lot : son éventuelle succession institutionnelle reste à vérifier sans effacer la garantie.")

add(17, """
<p>Lorsqu'une personne a été affiliée successivement ou simultanément au régime d'assurance vieillesse des ministres des cultes et des membres des congrégations et collectivités religieuses et à un ou plusieurs autres régimes obligatoires de base d'assurance vieillesse, les avantages que lui doit chaque régime se cumulent dans les conditions et, le cas échéant, les limites fixées par décret.</p>
""", "Le fait d'affiliation et le cumul des avantages sont formulés en une phrase plus directe. Le cumul favorable reste applicable aux futures affiliations éligibles ; la coordination des conditions et limites réglementaires reste nécessaire au calcul des droits.",
    "Ne pas remplacer les affiliations successives ou simultanées par une exigence de carrière salariée privée. Le texte concerne les avantages dus par chaque régime de base ; il ne supprime pas les régimes des cultes et ne fusionne pas leurs actifs. Aucune cotisation accessoire, demande d'agrément ou déclaration distincte n'est instituée par la source ; aucun avantage n'est abrogé.")

add(18, """
<p>Les versements mentionnés aux articles L. 351-14-1, L. 351-17, L. 643-2 et L. 653-5 du présent code et à l'article L. 9 bis du code des pensions civiles et militaires de retraite, ainsi que ceux prévus par des dispositions réglementaires de même objet, ne sont pas pris en compte pour bénéficier des dispositions des articles L. 351-1-1 et L. 351-1-3, des II et III des articles L. 643-3 et L. 653-2 du présent code, du 5° du I de l'article L. 24 et de l'article L. 25 bis du code des pensions civiles et militaires de retraite, de l'article 57 de la loi n° 2004-1370 du 20 décembre 2004 de financement de la sécurité sociale pour 2005 et du I de l'article 108 de la loi n° 2021-1754 du 23 décembre 2021 de financement de la sécurité sociale pour 2022. Cette exclusion ne s'applique pas aux versements mentionnés au IV de l'article L. 351-14-1 du présent code.</p>
""", "La longue règle d'exclusion est réécrite en conservant tous les renvois et en isolant son exception favorable. Les rachats restent possibles pour leurs autres effets ; leur non-prise en compte dans les dispositifs de départ visés conserve la distinction entre durées réellement requises et rachats. L'exception des anciens apprentis est maintenue pour toutes les futures liquidations éligibles, pas seulement pour les pensions déjà servies.",
    "L351-14-1 a été lu en entier, y compris les douze trimestres du I, les tarifs dérogatoires des II et III et le IV : seule l'exception de ce IV, liée aux contrats d'apprentissage conclus du 1er juillet 1972 au 31 décembre 2013, déroge ici à l'exclusion. Les autres avantages de rachat ne sont pas supprimés par le présent article. Le contrat unique ne rouvre pas cette période historique et ne retire pas le droit d'une future liquidation fondée sur ces anciens contrats. La note C du VIII de l'article 87 de la loi 2025-199 vise les pensions prenant effet à compter du 1er janvier 2026 ; les notes de la cible L351-14-1 conservent leur champ de 2023. Correction explicite de la coquille de titre « code des pensions civiles, militaires de retraite » en titre exact avec « et », sans changement de renvoi. Les textes extérieurs L9 bis, L24, L25 bis et les deux lois ne sont pas intégralement fournis ; leur coordination ne peut être attribuée aux règles du contrat privé.")

add(19, """
<p>Lorsque l'assuré décédé relevait simultanément de plusieurs régimes de protection sociale, un décret désigne le régime chargé de verser l'allocation de veuvage.</p>
""", "Le payeur de l'allocation est désigné dans une formulation directe, sans modifier la condition d'affiliations simultanées. L'allocation est une prestation favorable au survivant ; la suppression des impôts de succession n'emporte pas sa suppression.",
    "Conserver la simultanéité au moment où l'assuré décédé relevait des régimes, sans l'étendre silencieusement à toute affiliation successive. Le décret répartit la charge du versement, sans imposer une cotisation successorale. Les futurs bénéficiaires éligibles restent couverts et aucun régime particulier n'est artificiellement remplacé par le contrat unique.")

add(20, """
<p>Un décret fixe l'ordre de priorité du versement de l'allocation de veuvage et des autres prestations sociales soumises à des conditions de ressources.</p>
""", "La règle est réécrite sans changer le champ des prestations ni l'habilitation à fixer leur ordre de versement. Il s'agit de coordonner des prestations sous conditions de ressources, pas de créer une autorisation individuelle ou une taxe ; cette fonction reste nécessaire.",
    "Un ordre de priorité n'est pas une suppression de prestation ni un délai minimal nouveau. Les conditions de ressources restent celles des dispositifs concernés et aucun ordre concret n'est inventé. Ne pas confondre ces prestations avec l'impôt sur les transmissions par décès, ni appliquer à l'allocation le gel de certaines fractions de pensions de retraite prévu dans le projet distinct.")

add(21, """
<p>I. - Chaque année, un objectif de dépenses d'assurance maladie est défini. Il correspond au montant total des charges supportées par les régimes obligatoires d'assurance maladie au titre des activités suivantes :</p>
<p>1° Toutes les activités des établissements mentionnés à l'article L. 162-22-16 qui relèvent du 1° de l'article L. 162-22 ;</p>
<p>2° Les activités mentionnées au 3° du même article L. 162-22 ;</p>
<p>3° Toutes les activités de soins dispensées par l'Institution nationale des invalides ;</p>
<p>4° Les activités de soins dispensées par l'établissement public de santé territorial de Saint-Pierre-et-Miquelon ;</p>
<p>5° Les activités de soins dispensées par l'établissement public de santé de Mayotte ;</p>
<p>6° Les activités de soins dispensées par un hôpital établi dans un autre État à des patients relevant d'un régime obligatoire d'assurance maladie français, en application d'un accord conclu entre la France et cet État ;</p>
<p>7° Les activités de soins dispensées par les maisons d'enfants à caractère sanitaire mentionnées à l'article L. 2321-2 du code de la santé publique.</p>
<p>L'État arrête le montant de cet objectif en fonction de l'objectif national de dépenses d'assurance maladie. Ce montant tient compte des évolutions de toute nature qui placent, en tout ou partie, des établissements, services ou activités sanitaires ou médico-sociaux sous un régime juridique ou de financement différent de leur régime antérieur. Il peut être corrigé en fin d'année pour tenir compte de ces évolutions lorsqu'elles sont intervenues en cours d'année.</p>
<p>Le montant de l'objectif mentionné au premier alinéa du présent I est réparti en dotations régionales. Certaines dépenses comprises dans cet objectif peuvent toutefois rester en dehors de ces dotations. L'État fixe le montant des dotations régionales en tenant compte de l'activité des établissements, des orientations du projet régional ou interrégional de santé et des priorités nationales ou locales de politique sanitaire.</p>
<p>II. - L'État arrête le montant de la dotation annuelle de financement de chaque établissement.</p>
""", "Réécriture intégrale de l'objectif et de ses sept catégories, avec phrases plus courtes pour la correction de périmètre et la répartition régionale. Toutes les possibilités favorables d'adaptation sont conservées. Les décisions d'allocation de fonds publics et l'annualité budgétaire ont une fonction essentielle de financement des soins ; aucun prélèvement accessoire ni dépôt redondant de dossier n'est créé par cet article et aucune coupe ne lui est artificiellement imputée.",
    "Conserver I, ses sept numéros, les deux alinéas de fixation/répartition et II. La possibilité de dépenses hors dotation régionale et la correction de fin d'année restent ouvertes aux futures situations éligibles. La note de l'article 34 VI de la loi 2019-1446, reportée par l'article 51 VI de la loi 2020-1576, fixe l'entrée en vigueur historique au 1er janvier 2022. Incohérence préexistante à coordonner explicitement : L162-22-16, dans sa source plus récente du corpus, finance les activités des 1° et 2° de L162-22 pour les établissements concernés, alors que le 1° de L174-1 ne cite que le 1°. Le présent texte conserve ce champ source et ne prétend pas trancher la coordination de psychiatrie par une extension silencieuse. L162-22 et L162-22-19 ont aussi été lus en entier ; L2321-2 du code de la santé publique reste un renvoi extérieur non reconstitué. L'annualité de ce financement hospitalier ne rétablit aucune annualité de l'IS à la distribution.",
    benefit="Le financement des soins des sept catégories demeure : établissements visés par L162-22-16 pour le 1° de L162-22, activités du 3°, Institution nationale des invalides, Saint-Pierre-et-Miquelon, Mayotte, hôpitaux étrangers dans le cadre d'un accord et maisons d'enfants sanitaires. La correction de fin d'année en cas de changement de régime juridique ou financier reste possible. La faculté de laisser certaines dépenses hors des dotations régionales est expressément conservée, sans limitation aux dossiers anciens. Les dotations continuent de tenir compte de l'activité, des orientations régionales ou interrégionales et des priorités nationales ou locales. Aucun de ces mécanismes favorables n'est supprimé ou conditionné à une nouvelle pièce. Le texte ne porte pas d'exonération fiscale ; son champ de financement reste intégralement présent, sous la réserve explicite de concordance des renvois signalée dans review_notes.")

add(22, """
<p>Le directeur général de l'agence régionale de santé peut, par arrêté, transférer une part de la dotation régionale mentionnée à l'article L. 174-1 au fonds d'intervention régional prévu à l'article L. 1435-8 du code de la santé publique. Il peut également transférer vers cette dotation régionale une part du fonds d'intervention régional dont la gestion est déléguée à l'agence. Ces transferts ne peuvent, au total, diminuer l'une ou l'autre des dotations concernées de plus de 1 % du montant des dotations régionales concernées. Aucun montant intermédiaire inférieur à cette limite ne peut leur être opposé sur le seul fondement du présent article.</p>
<p>Les transferts effectués en cours d'année sont pris en compte en fin d'année en corrigeant, d'une part, le montant de l'objectif mentionné à l'article L. 174-1 et, d'autre part, la dotation mentionnée au 1° de l'article L. 1435-9 du code de la santé publique.</p>
<p>La suppression de la fixation ministérielle d'un montant intermédiaire s'applique aux décisions de transfert prises à compter de l'entrée en vigueur de la loi portant la présente rédaction. Les transferts décidés antérieurement restent régis par les règles qui leur étaient applicables ; ils n'ont pas à être décidés de nouveau.</p>
""", "La faculté de transfert dans les deux sens est conservée et réécrite directement. Réforme de fond : suppression de l'arrêté ministériel fixant un plafond intermédiaire à l'intérieur du plafond légal de 1 %. La limite légale demeure, ainsi que l'arrêté du directeur général et la correction comptable de fin d'année ; aucun circuit déclaratif ne remplace la fixation ministérielle supprimée.",
    "Le 1 % garde pour référence le montant des dotations régionales concernées, sans le convertir en pourcentage du seul mouvement ou de la totalité nationale du fonds. Le total des transferts ne permet pas de contourner cette protection par plusieurs décisions. La suppression vise seulement le plafond ministériel intermédiaire du premier alinéa, sans supprimer les contrôles budgétaires autonomes ni augmenter l'enveloppe de l'assurance maladie. Coordonner les arrêtés pris sur ce seul fondement pour les décisions nouvelles. Conserver la double correction de L174-1 et du 1° de L1435-9. L1435-8 et L1435-9 sont extérieurs au corpus fourni ; leur texte n'est pas inventé. L'entrée en vigueur historique au 1er janvier 2022 demeure celle de la note commune aux articles de financement, sans la confondre avec cette simplification.",
    ["Fixation obligatoire par arrêté des ministres d'un montant maximal intermédiaire pour les transferts régionaux, à l'intérieur de la limite légale de 1 %."])

add(23, """
<p>La caisse primaire d'assurance maladie dans la circonscription de laquelle l'établissement est implanté verse, pour le compte de tous les régimes d'assurance maladie, les dotations annuelles prévues aux articles L. 162-22-16, L. 162-22-19 et L. 174-1. Une convention entre les régimes peut confier ce rôle à une caisse relevant d'un autre régime.</p>
<p>Un décret en Conseil d'État fixe les modalités d'application du présent article.</p>
""", "Le payeur commun est placé en tête et la faculté conventionnelle de désigner une autre caisse reste ouverte. La règle organise déjà un versement pour tous les régimes ; sa suppression recréerait une fragmentation de paiement sans retirer une démarche imposée par la source. Réécriture à droit constant, sans nouvelle formalité pour les établissements.",
    "Conserver les trois renvois, la circonscription d'implantation et la dérogation conventionnelle, pour les conventions futures également. L162-22-16 et L162-22-19 ont été lus en entier dans le corpus ; le second couvre notamment les dotations de psychiatrie et n'est pas absorbé par le seul périmètre de L174-1. La note d'entrée en vigueur au 1er janvier 2022 est historique et ne fixe aucune date de promulgation du projet. Le versement interrégimes et la convention facultative restent nécessaires à la continuité du financement ; aucun second dépôt de dossier ou nouvelle déclaration n'est ajouté.")


# Les trois cibles de droit du travail sont requises pour huit sources,
# même lorsque leur régime de rupture est sans application à la prestation.
